#!/usr/bin/env node
/**
 * "Dumb" Stop hook — GUARANTEES a review is asked for, does NOT perform it itself.
 *
 * No token, no network, no SDK: it just reads the local git state and checks that
 * the project's rules index (.claude/coding-rules.md, generated by the resolver)
 * exists, then returns a decision in the format expected by Claude Code on
 * stdout. The plugin itself ships NO rules — they come from the consumer project.
 *
 * ## What counts as "work to review": the review base
 *
 * Everything below is measured against a BASE COMMIT, never against HEAD.
 * `git diff <base>` compares the base to the WORKING TREE, so committing — which
 * only moves content between the index and HEAD — leaves the changed set and its
 * contents identical. Two consequences, and both are the point:
 *
 *  - a task that commits its work before handing back does NOT escape the gate
 *    (with HEAD as the base its tree is clean and there is nothing left to see);
 *  - committing already-reviewed work does NOT re-trigger a review, because the
 *    fingerprint below is invariant under committing.
 *
 * The base is resolved, in order:
 *  1. the newest commit on record as reviewed-and-accepted that is an ancestor of
 *     HEAD — whichever branch settled it. A branch started from an already
 *     reviewed branch therefore inherits its base instead of restarting;
 *  2. `git merge-base origin/<default> HEAD` — first run, or state lost;
 *  3. HEAD — no origin, no default ref, shallow clone, detached checkout.
 *
 * (1) is what keeps the reviewed set minimal and topology-agnostic: it works the
 * same on a branch stacked on another branch, where (2) would drag in the parent
 * branch's commits. No `fetch` is ever run: a stale origin ref widens the
 * reviewed set, it never makes it wrong.
 *
 * ## What keeps this from over-firing
 *
 * A content-aware fingerprint of the working tree (vs the same base), stored in
 * `.git/` between invocations, per branch:
 *
 *  - Anti-repeat: the changed set is cumulative until the base moves, so a turn
 *    that changes NOTHING (e.g. the user just asked a question) still shows
 *    earlier work. If the fingerprint equals the last settled review, we let
 *    Claude finish instead of re-reviewing.
 *
 *  - Review-until-stable: when a review pass edits code, those edits are
 *    themselves re-reviewed. We keep forcing a pass as long as the fingerprint
 *    keeps changing, and stop once a pass changes nothing (converged) — capped
 *    at MAX_PASSES so a non-converging review can't loop forever.
 *
 * `stop_hook_active` (set by Claude Code inside a Stop-triggered continuation)
 * is what tells a review pass apart from a fresh user turn.
 *
 * Note on the guarantee: this hook forces a turn dedicated to the review. It
 * cannot verify that the review actually happened, or that it was any good.
 *
 * Output contract:
 *   { "decision": "block", "reason": "<...>" }  => Claude continues (re-reads/fixes)
 *   {}                                            => Claude can finish
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";

// Rules INDEX, generated by the resolver. Same artifact as the one imported by
// the project's CLAUDE.md → zero drift. It lists the modules and references them
// with `@`; it does not contain their text.
const COMPOSED_RULES = join(process.cwd(), ".claude", "coding-rules.md");

// The project's rules config (the resolver's input), checked in the two places
// the resolver itself looks. Its presence signals intent to use the plugin.
const CONFIG_FILES = [
  join(process.cwd(), "coding-rules.config.yml"),
  join(process.cwd(), ".claude", "coding-rules.config.yml"),
];

// The plugin's own generated artifacts aren't "work to review" — regenerating
// the index, or the materialized copies of the git/npm packs it references,
// shouldn't trigger a review pass on its own.
const SELF_FILES = [".claude/coding-rules.md"];
const SELF_DIRS = [".claude/rule-packs/"];

function isSelf(file) {
  return SELF_FILES.includes(file) || SELF_DIRS.some((d) => file.startsWith(d));
}

// Upper bound on consecutive review passes within a single task. A review pass
// that edits code gets re-reviewed; we stop once a pass changes nothing, or
// after this many passes if the review never converges (safety against loops).
const MAX_PASSES = 3;

// Refs tried, in order, to find the branch the work forked from when no settled
// base is on record. `origin/HEAD` (queried first, below) is the authoritative
// one; these cover clones where it was never set, then repos with no remote at
// all — without the local entries, a local-only repo has no fork point to find
// and every branch falls back to HEAD, which is the hole this hook exists to close.
const DEFAULT_BRANCH_REFS = [
  "refs/remotes/origin/main",
  "refs/remotes/origin/master",
  "refs/heads/main",
  "refs/heads/master",
];

// Bumped when the shape of the state file changes; an older file simply fails to
// parse as current, which costs one extra review pass and then self-heals.
const STATE_VERSION = 2;

// Upper bound on branches kept in the state file. Entries are re-inserted on
// write, so key order is LRU and the oldest are dropped first. Keeps the
// per-run cost of scanning recorded bases bounded in a long-lived clone.
const MAX_BRANCH_ENTRIES = 50;

// Branch names are used as object keys in the state file. Prefixing keeps them
// out of `Object.prototype` territory (a branch may legitimately be named
// `__proto__` or `constructor`).
const BRANCH_KEY_PREFIX = "b:";

function allow() {
  process.stdout.write(JSON.stringify({}));
  process.exit(0);
}

function block(reason) {
  process.stdout.write(JSON.stringify({ decision: "block", reason }));
  process.exit(0);
}

async function readStdin() {
  try {
    const chunks = [];
    for await (const c of process.stdin) chunks.push(c);
    return Buffer.concat(chunks).toString("utf8");
  } catch {
    return "";
  }
}

function git(args) {
  return execFileSync("git", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    maxBuffer: 64 * 1024 * 1024,
  });
}

function lines(out) {
  return out
    .split("\n")
    .map((f) => f.trim())
    .filter(Boolean);
}

// Untracked (new) files. `--exclude-standard` makes git honor
// .gitignore/.git/info/exclude, so ignored files (build output, deps, generated
// artifacts…) never appear.
function untrackedFiles() {
  try {
    return lines(git(["ls-files", "--others", "--exclude-standard"]));
  } catch {
    return [];
  }
}

// Files changed between `base` and the WORKING TREE, plus untracked ones.
// No language/extension assumptions: the project's rules decide relevance.
function changedFiles(base) {
  const tracked = [];
  if (base !== null) {
    try {
      tracked.push(...lines(git(["diff", "--name-only", base])));
    } catch {
      // Bad base / no history → fall back to the untracked files alone rather
      // than reporting "nothing to review".
    }
  }
  const seen = new Set();
  return [...tracked, ...untrackedFiles()]
    .filter((f) => !isSelf(f))
    .filter((f) => (seen.has(f) ? false : (seen.add(f), true)));
}

function rulesPresent() {
  return existsSync(COMPOSED_RULES);
}

// The project shows intent to use coding-standards if it has either the rules
// index or a config to generate it. When NEITHER exists, the plugin isn't
// adopted here → the hook stays silent instead of nagging.
function adopted() {
  return existsSync(COMPOSED_RULES) || CONFIG_FILES.some(existsSync);
}

// Path of the per-repo state file that holds the last-reviewed fingerprint and
// base, keyed by branch. Lives inside .git/ → never tracked, never committed,
// auto-scoped to the repo. Returns null when we're not in a git repo (then
// fingerprinting is skipped).
function stateFile() {
  try {
    return join(git(["rev-parse", "--git-dir"]).trim(), "coding-standards-stop.fingerprint");
  } catch {
    return null;
  }
}

function revParse(rev) {
  try {
    return git(["rev-parse", "--verify", "--quiet", rev]).trim() || null;
  } catch {
    return null; // empty repo, or unknown rev
  }
}

// Branch key for the state file. A detached checkout reports "HEAD", which is a
// fine bucket: base resolution falls back on its own there.
function currentBranch() {
  try {
    return git(["rev-parse", "--abbrev-ref", "HEAD"]).trim() || "HEAD";
  } catch {
    return "HEAD";
  }
}

function isAncestor(rev, of) {
  if (!rev) return false;
  try {
    git(["merge-base", "--is-ancestor", rev, of]); // exits non-zero when false
    return true;
  } catch {
    return false;
  }
}

// Fork point vs the default branch, used only when no settled base is on record.
// Deliberately offline: whatever the local refs say is good enough — a stale one
// widens the reviewed set, it never makes it wrong. On the default branch itself
// the merge-base is HEAD, so behaviour there is unchanged.
function forkPointFromDefault() {
  const refs = [];
  try {
    const head = git(["symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"]).trim();
    if (head) refs.push(head);
  } catch {
    // origin/HEAD unset (common in CI clones) → try the usual names below.
  }
  refs.push(...DEFAULT_BRANCH_REFS);

  for (const ref of refs) {
    try {
      const base = git(["merge-base", ref, "HEAD"]).trim();
      if (base) return base;
    } catch {
      // Ref doesn't exist here → next candidate.
    }
  }
  return null;
}

// Number of commits between `base` and HEAD, i.e. how much of this branch's
// history is NOT yet accounted for by that base. null when it can't be counted.
function distanceToHead(base) {
  try {
    const n = Number.parseInt(git(["rev-list", "--count", base + "..HEAD"]).trim(), 10);
    return Number.isInteger(n) ? n : null;
  } catch {
    return null;
  }
}

// Every base ever settled, across branches. A base recorded on another branch is
// only usable if it is an ancestor of HEAD — resolveBase checks that.
function recordedBases(store) {
  if (!store) return [];
  const bases = new Set();
  for (const key of Object.keys(store.branches)) {
    const entry = store.branches[key];
    if (entry && typeof entry.base === "string") bases.add(entry.base);
  }
  return [...bases];
}

// See the module docstring: nearest reviewed ancestor → fork point → HEAD → null.
function resolveBase(store) {
  const head = revParse("HEAD");
  if (head === null) return null; // empty repo

  let nearest = null;
  let shortest = Infinity;
  for (const base of recordedBases(store)) {
    if (!isAncestor(base, "HEAD")) continue; // belongs to another line of work
    const distance = distanceToHead(base);
    if (distance !== null && distance < shortest) {
      shortest = distance;
      nearest = base;
    }
  }

  return nearest || forkPointFromDefault() || head;
}

// Content-aware snapshot of the changed set: for each path, its bytes in the
// WORKING TREE (a removal is recorded as such). Deliberately NOT a hash of the
// `git diff` output: a newly created file shows up as an untracked path before a
// commit and as a diff hunk after, so hashing the diff would change across a
// commit that changed no content at all — and a spurious review would fire.
// Hashing content instead makes the fingerprint invariant under committing,
// which is what lets the anti-repeat and review-until-stable logic below work
// against a base that is not HEAD.
function fingerprintOf(files) {
  const h = createHash("sha256");
  for (const f of [...files].sort()) {
    h.update("\0" + f + "\0");
    try {
      h.update(readFileSync(f));
    } catch {
      h.update("\0deleted\0"); // changed vs the base by no longer being there
    }
  }
  return h.digest("hex");
}

// State, per branch = { fp, passes, base }:
//   passes === 0  → fp is a settled/accepted baseline (last review converged).
//   passes >= 1   → we're in a review chain; fp is the state last sent for
//                   review, passes is how many review passes have run so far.
//   base          → the commit everything is measured against (see resolveBase).
function readStore(path) {
  if (!path || !existsSync(path)) return null;
  try {
    const store = JSON.parse(readFileSync(path, "utf8"));
    if (store && store.version === STATE_VERSION && store.branches) return store;
  } catch {}
  return null; // absent, unreadable, or written by an older version
}

function branchState(store, branch) {
  if (!store) return null;
  const s = store.branches[BRANCH_KEY_PREFIX + branch];
  if (s && typeof s.fp === "string" && Number.isInteger(s.passes)) return s;
  return null;
}

function writeState(path, branch, fp, passes, base) {
  if (!path || fp === null) return;
  const store = readStore(path) || { version: STATE_VERSION, branches: {} };
  const key = BRANCH_KEY_PREFIX + branch;
  delete store.branches[key]; // re-insert last so key order stays LRU
  store.branches[key] = { fp, passes, base: base ?? null };
  const keys = Object.keys(store.branches);
  for (const stale of keys.slice(0, Math.max(0, keys.length - MAX_BRANCH_ENTRIES))) {
    delete store.branches[stale];
  }
  try {
    writeFileSync(path, JSON.stringify(store));
  } catch {}
}

// Record that everything up to HEAD has been reviewed and accepted: the base
// moves to HEAD, and the fingerprint is recomputed against that same base so the
// pair stays consistent. Any work still uncommitted stays covered by the
// fingerprint, so it isn't re-reviewed either.
function settle(path, branch) {
  if (!path) return;
  const base = revParse("HEAD");
  writeState(path, branch, fingerprintOf(changedFiles(base)), 0, base);
}

function buildReason(files, hasRules) {
  const head = [
    "⏸️ Mandatory review before finishing (Stop hook).",
    "",
    "Changed since the last accepted review (committed or not):",
    ...files.map((f) => `- ${f}`),
    "",
  ];

  // The rule modules are already in context (the index is imported by CLAUDE.md,
  // and Claude Code auto-loads `.claude/rules/`), so we point at the index rather
  // than pasting anything into this message.
  if (!hasRules) {
    return [
      ...head,
      "The rules index `.claude/coding-rules.md` is missing — run",
      "`/update-coding-rules` to generate it, then review the files above.",
    ].join("\n");
  }

  return [
    ...head,
    "Re-read `.claude/coding-rules.md` — it indexes every rule module in force —",
    "and check the files above against those modules. Fix every violation of",
    "severity **major** or **critical**; report the **minor** / **info** ones",
    "(ignore WARN-ONLY modules as blocking).",
    "Once fixed, finish normally (this hook will not ask you again).",
  ].join("\n");
}

async function main() {
  const rawInput = await readStdin();
  let input = {};
  try {
    input = rawInput ? JSON.parse(rawInput) : {};
  } catch {
    input = {};
  }

  // Not adopted here (neither a rules index nor a config) → the plugin isn't in
  // use in this project; do nothing.
  if (!adopted()) return allow();

  const statePath = stateFile();
  const branch = currentBranch();
  const store = readStore(statePath);
  const prev = branchState(store, branch);
  const base = resolveBase(store);
  const files = changedFiles(base);
  const fp = statePath ? fingerprintOf(files) : null;

  // A) Nothing changed since the base → nothing to review; settle a baseline.
  if (files.length === 0) {
    settle(statePath, branch);
    return allow();
  }

  if (input.stop_hook_active === true) {
    // We're inside the review chain we forced earlier.
    if (fp !== null && prev && prev.fp === fp) {
      // The review pass changed nothing → converged → accept as baseline.
      settle(statePath, branch);
      return allow();
    }
    // The review edited code → re-verify those edits, but cap the number of
    // passes so a review that never converges can't loop forever.
    const passes = prev ? prev.passes : 1;
    if (passes >= MAX_PASSES) {
      settle(statePath, branch);
      return allow();
    }
    // Keep the chain's base: the set under review must not shrink mid-review.
    writeState(statePath, branch, fp, passes + 1, base);
    return block(buildReason(files, rulesPresent()));
  }

  // Fresh user turn (not a review continuation).
  // B) Unchanged since the last settled review → don't re-trigger (e.g. the user
  //    just asked a question, or the work was merely committed as-is).
  if (fp !== null && prev && prev.passes === 0 && prev.fp === fp) {
    settle(statePath, branch);
    return allow();
  }

  // C) New / unreviewed work → start a review chain.
  writeState(statePath, branch, fp, 1, base);
  return block(buildReason(files, rulesPresent()));
}

main().catch(() => allow()); // on error, never block the dev
